   if(!strcasecmp(tag,"a")){char href[512];if(ex_attribute(&t,"href",href,sizeof href)&&d->link_count<512){struct ep_link*r=d->links+d->link_count;if(ez_resolve(base,href,r->path,r->fragment)){f.link=++d->link_count;f.style.flags|=EP_UNDERLINE;f.style.colored=1;f.style.color=0x253a;}}}
